def clean(s):
 s=str(s).replace('AI06','AI-06')
 s=re.sub(r'\b(Stage|Development|final|Ammer|Serbe|FlyVis|PyTorch|Python|RTX|torchvision|ON|DSI|represents|further|held-out|on|to|by|below|times|length|full|central|fixed|most|magnitude|is|plus|tolerance|error|difference|direction|about|autograd|amendment|all|both|and|at|over|among|models|model|strengths|strength|speed|Batch|batch|epsilon|frame|trajectory|within|than|passed for)(?=\d)',r'\1 ',s)
 s=re.sub(r'(?<=\d)(?=degrees|minutes|seconds|trajectories|cells|model-voltage|percent)',r' ',s)
 s=re.sub(r';(?=\S)','; ',s)
 return s

def title(s):s=clean(s);story.append(Paragraph(html.escape(s),styles['TitleAI']));md.append('# '+s.replace('\n',' ')+'\n')
def h(s):s=clean(s);story.append(Paragraph(s,styles['Heading2']));md.append('## '+s+'\n')
def para(s,small=False):
 s=clean(s)
 s=re.sub(r'\b(all|both|and|at|about|over|among|models|model|strengths|strength|speed|Batch|batch|epsilon|frame|trajectory|within|than|passed for)(?=\d)',r'\1 ',s)
 s=re.sub(r'(?<=\d)(?=degrees|degrees/s|minutes|seconds|trajectories|cells|model-voltage|percent)',r' ',s)
 story.append(Paragraph(s,styles['SmallAI' if small else 'BodyAI']));txt=re.sub(r'<link href="([^"]+)"[^>]*>(.*?)</link>',r'[\2](\1)',s);md.append(re.sub('<[^>]+>','',txt.replace('<br/>','\n').replace('<b>','**').replace('</b>','**'))+'\n')
def table(headers,rows,widths):
 headers=[clean(x) for x in headers];rows=[[clean(x) for x in row] for row in rows];data=[[Paragraph(html.escape(str(x)),styles['SmallAI']) for x in row] for row in [headers]+rows];t=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT');t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e8f0f3')),('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,0),.6,colors.HexColor('#98b0b9')),('LINEBELOW',(0,1),(-1,-1),.25,colors.HexColor('#dce5e8')),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),5)]));story.extend([t,Spacer(1,9)]);esc=lambda x:str(x).replace('|','\\|');md.append('| '+' | '.join(map(esc,headers))+' |\n| '+' | '.join(['---']*len(headers))+' |\n'+'\n'.join('| '+' | '.join(map(esc,row))+' |' for row in rows)+'\n')
def fmt(x,n=3):return 'undefined' if x is None else f'{x:.{n}f}'
def page():story.append(PageBreak());md.append('\n---\n')
def link(label,url):return f'<link href="{url}" color="#246a81">{label}</link>'
def evidence(label,rel):return link(label,'../'+rel)
def finite_metric(subset,s,metric):return next(x for x in finite if x['subset']==subset and x['strength']==s)['metrics'][metric]

title('AI06 Stage 1\nEstimating silencing effects')
para('Cell-type reference in four released FlyVis models<br/>3 October 2026 | frozen 2 October | AI interpretability portfolio')
h('What was completed')
para(f'The four-model study ran locally on the 6 GB NVIDIA GPU. It covers all65 model compartments and eight predeclared pairs, strengths0.5 and1.0, and48 moving-edge trajectories per model/intervention. The exact reference represents28,224 main trajectories; structural zeros reduce simulated main trajectories to27,456. A further1,344 trajectories cover the separate biology-speed panel. Saved-metric verification and independent aggregation passed. Reporting corrections apply the predeclared DSI validity limit and match permutation coverage; severe voltage amplification remains a model limitation.')
table(['Subset','Strength','First-order MAE','Gradient rank','Count rank','Current rank'],[[sub,str(s),fmt(finite_metric(sub,s,'first_order/mae')['mean']),fmt(finite_metric(sub,s,'first_order/mean_spearman')['mean']),fmt(finite_metric(sub,s,'synapse_count/mean_spearman')['mean']),fmt(finite_metric(sub,s,'native_current/mean_spearman')['mean'])] for sub in ['all','final'] for s in [.5,1.]],[70,52,94,92,92,92])
para(f"On the two held-out models at full attenuation, first-order MAE averages {finite_metric('final',1.,'first_order/mae')['mean']:.3f} DSI units, with model range {finite_metric('final',1.,'first_order/mae')['range'][0]:.3f}-{finite_metric('final',1.,'first_order/mae')['range'][1]:.3f}. The corresponding mean importance recall is {finite_metric('final',1.,'first_order/recall_at_010')['mean']:.3f}. These finite-set results quantify the approximation directly; they do not validate every local gradient as a stable sensitivity.")
para('MAE is absolute DSI units; rank is mean Spearman association with exact absolute effects. The final subset contains only models001 and005. Connectivity and intact currents are uncalibrated rankings, so no effect-size MAE is invented for them. Full per-model results follow.')
h('Main boundaries')
para('The first-order estimator is a fixed autograd local branch/subgradient. A development finite-difference failure exposed nearly tied response peaks; an independent tangent recurrence checked the implementation. Peak sensitivity remains flagged, and no smoothing or favorable tie rule was fitted.')
para('Pair contrasts are evaluated on raw voltage and DSI separately. The Ammer speed match is implemented, but experimental readouts and silencing mechanisms remain unmatched; biological correctness is <b>not tested under matched conditions</b>. This is a cell-type reference, not a complete causal map or an externally reviewed scientific result.')
para(f'AI-assisted implementation, analysis and writing. Recorded study GPU-worker time, a lower bound after interruption: {actual["study_wall_hours"]:.3f}h; prospective allowance: {cost["options"]["cuda"]["projected_total_hours"]:.2f}h. Qualification records and failed attempts remain preserved.',True)
page()

