title('4  The eight pair interactions')
para('Interaction is joint minus single A minus single B plus baseline, at equal attenuation strength. This four-condition contrast is computed separately on each DSI and each directional raw-voltage mean, integral and peak. A DSI contrast alone cannot establish nonlinear voltage integration.')
para(f"{len(set(tuple(x['pair']) for x in pairs if x['max_abs_dsi'] is not None and x['max_abs_dsi']>=.01))} of the eight pairs have at least one DSI interaction of magnitude0.01 or greater in this finite panel. The largest absolute raw-mean interaction is {max(x['max_abs_raw_mean'] for x in pairs):.3f} model-voltage units. The table preserves model and strength rather than treating every contrast as an independent experiment.")
table(['Model','s','Largest |DSI interaction|','DSI contrasts >=0.01 / eligible','Largest |raw mean interaction|'],[[model,str(s),fmt(max(x['max_abs_dsi'] for x in pairs if x['model']==model and x['strength']==s)),str(sum(x['dsi_at_least_001_count'] for x in pairs if x['model']==model and x['strength']==s))+' / '+str(sum(x['dsi_eligible_count'] for x in pairs if x['model']==model and x['strength']==s)),fmt(max(x['max_abs_raw_mean'] for x in pairs if x['model']==model and x['strength']==s))] for model in ['000','004','001','005'] for s in [.5,1.]],[48,32,135,142,135])
